CREATE TABLE users(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),name TEXT,email TEXT,password TEXT,role TEXT,department TEXT,target_role TEXT,daily_goal INTEGER);
CREATE TABLE questions(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),kind TEXT,topic TEXT,difficulty TEXT,prompt TEXT,options TEXT,answer INTEGER,explanation TEXT);
CREATE TABLE quiz_attempts(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),user_id BIGINT NOT NULL REFERENCES users(id),kind TEXT,status TEXT,question_ids TEXT,answers TEXT,score INTEGER,total INTEGER,duration_seconds INTEGER,elapsed_seconds INTEGER,details TEXT);
CREATE INDEX quiz_attempts_user_idx ON quiz_attempts(user_id,created_at DESC);
CREATE TABLE bookmarks(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),user_id BIGINT NOT NULL REFERENCES users(id),question_id BIGINT NOT NULL REFERENCES questions(id));
CREATE INDEX bookmarks_user_idx ON bookmarks(user_id,created_at DESC);
CREATE TABLE coding_problems(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),title TEXT,topic TEXT,difficulty TEXT,description TEXT,constraints_text TEXT,tests TEXT,hints TEXT,solution TEXT,complexity TEXT);
CREATE TABLE coding_submissions(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),user_id BIGINT NOT NULL REFERENCES users(id),problem_id BIGINT NOT NULL REFERENCES coding_problems(id),language TEXT,code TEXT,status TEXT,details TEXT);
CREATE INDEX coding_submissions_user_idx ON coding_submissions(user_id,created_at DESC);
CREATE TABLE resume_reviews(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),user_id BIGINT NOT NULL REFERENCES users(id),filename TEXT,target_role TEXT,score INTEGER,report TEXT);
CREATE INDEX resume_reviews_user_idx ON resume_reviews(user_id,created_at DESC);
CREATE TABLE interview_questions(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),category TEXT,role TEXT,prompt TEXT,model_answer TEXT,key_points TEXT);
CREATE TABLE interview_sessions(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),user_id BIGINT NOT NULL REFERENCES users(id),role TEXT,category TEXT,status TEXT,duration_seconds INTEGER,elapsed_seconds INTEGER,questions TEXT,answers TEXT,score INTEGER);
CREATE INDEX interview_sessions_user_idx ON interview_sessions(user_id,created_at DESC);
CREATE TABLE learning_goals(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),user_id BIGINT NOT NULL REFERENCES users(id),title TEXT,due_date TEXT,completed BOOLEAN);
CREATE INDEX learning_goals_user_idx ON learning_goals(user_id,created_at DESC);
ALTER TABLE users ADD CONSTRAINT user_email_unique UNIQUE(email);
ALTER TABLE bookmarks ADD CONSTRAINT bookmark_unique UNIQUE(user_id,question_id);
ALTER TABLE questions ADD CONSTRAINT valid_answer CHECK(answer BETWEEN 0 AND 3);
